/**
 * Worker entry: the OpenNext-built Next.js app plus a cron handler that
 * processes sources stored but not yet processed (lib/scheduled.ts).
 */

// Generated by `npm run cf:build`, so it is missing until a build runs. The
// OpenNext docs use @ts-ignore here: @ts-expect-error fails once it exists.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import { default as app } from "./.open-next/worker.js";
import { drainThroughApp } from "./lib/scheduled";

const worker = {
  fetch: app.fetch,
  scheduled: (_controller: unknown, env: object, ctx: unknown) =>
    drainThroughApp(app.fetch, env, ctx),
};

export default worker;
